                        "CreditShoppingPrudentRefresh": {
                            "next": [
                                "CreditShoppingBuyItemBelowReserve",
                                "CreditShoppingBuyFailed",
                                "CreditShoppingBuyConfirm"
                            ]
                        }
                    }
                },
                {
                    "name": "No",
                    "pipeline_override": {
                        "CreditShoppingRefreshCountReached": {
                            "next": [
                                "CreditShoppingBuyFailed",
                                "CreditShoppingBuyConfirm"
                            ]
                        },
                        "CreditShoppingPrudentRefresh": {
                            "next": [
                                "CreditShoppingBuyFailed",
                                "CreditShoppingBuyConfirm"
                            ]
                        }
                    }
                }
            ]
        },
        "PrudentRefresh": {
            "type": "switch",
            "label": "$option.PrudentRefresh.label",
            "description": "$option.PrudentRefresh.description",
            "default_case": "No",
            "cases": [
                {
                    "name": "Yes",
                    "option": [
                        "PrudentRefreshThreshold"
                    ],
                    "pipeline_override": {
                        "CreditShoppingPrudentRefresh": {
                            "enabled": true
                        }
                    }
                },
                {
                    "name": "No",
                    "pipeline_override": {
                        "CreditShoppingPrudentRefresh": {
                            "enabled": false
                        }
                    }
                }
            ]
