        "PrudentRefreshThreshold": {
            "type": "input",
            "label": "$option.PrudentRefresh.inputs.PrudentRefreshThreshold.label",
            "description": "$option.PrudentRefresh.inputs.PrudentRefreshThreshold.description",
            "inputs": [
                {
                    "name": "PrudentRefreshThreshold",
                    "label": "$option.PrudentRefresh.inputs.PrudentRefreshThreshold.label",
                    "description": "$option.PrudentRefresh.inputs.PrudentRefreshThreshold.description",
                    "pipeline_type": "int",
                    "verify": "^\\d+$",
                    "default": "400"
                }
            ],
            "pipeline_override": {
                "CreditShoppingPrudentRefresh": {
                    "recognition": {
                        "type": "And",
                        "param": {
                            "all_of": [
                                {
                                    "recognition": {
                                        "type": "Custom",
                                        "param": {
                                            "custom_recognition": "ExpressionRecognition",
                                            "custom_recognition_param": {
                                                "expression": "{CreditShoppingReserveCreditOCRInternal}-{RefreshCost}<{PrudentRefreshThreshold}"
                                            }
                                        }
                                    }
                                },
                                {
                                    "recognition": {
                                        "type": "And",
                                        "param": {
                                            "all_of": [
                                                "CreditIcon",
                                                "NotSoldOut",
                                                "CanAfford"
                                            ],
                                            "box_index": 2
                                        }
                                    }
                                }
                            ],
                            "box_index": 1
                        }
                    }
                }
            }
        },
